def compute(vars):
    value_2010 = vars["v1"]
    value_2009 = vars["v2"]

    if value_2009 == 0:
        return None

    change = value_2010 - value_2009
    percent_change = (change / value_2009) * 100

    return {
        "value": percent_change,
        "trace": {
            "value_2010": value_2010,
            "value_2009": value_2009,
            "change": change,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
